import collections

def ii():
	return int(input())

def mi():
	return map(int, input().split())

def li():
	return list(map(int, input().split()))
for i in range(ii()):
	n = ii()
	A = li()
	B = li()
	temp = 1
	for i in range(n):
		if A[i] < B[i]:
			temp = 0
	if temp == 0:
		print(-1)
	else:
		D = collections.deque([])
		ans = 0
		for i in range(n):
			while D and D[-1] < B[i]:
				D.pop()
			while D and D[0] > A[i]:
				D.popleft()
			if A[i] != B[i]:
				if len(D) == 0:
					ans += 1
					D.append(B[i])
				elif B[i] != D[-1]:
					ans += 1
					D.append(B[i])
		print(ans)
